package com.courseinsight.server.dto;

import com.courseinsight.server.entity.AnalysisBatchStatus;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDateTime;

public record AnalysisBatchProgressResponse(
        Long batchId,
        String batchNo,
        Long courseId,
        String originalFilename,
        String status,
        int totalCount,
        int waitingCount,
        int processingCount,
        int retryingCount,
        int successCount,
        int failedCount,
        BigDecimal completionPercentage,
        LocalDateTime createdAt,
        LocalDateTime completedAt) {

    public static AnalysisBatchProgressResponse from(
            AnalysisBatchProgressAggregate aggregate) {
        int total = aggregate.getTotalCount();
        int waiting = toInt(aggregate.getWaitingCount());
        int processing = toInt(aggregate.getProcessingCount());
        int retrying = toInt(aggregate.getRetryingCount());
        int success = toInt(aggregate.getSuccessCount());
        int failed = toInt(aggregate.getFailedCount());
        int completed = success + failed;

        AnalysisBatchStatus status = resolveStatus(total, success, failed);
        BigDecimal percentage = BigDecimal.valueOf(completed)
                .multiply(BigDecimal.valueOf(100))
                .divide(BigDecimal.valueOf(total), 2, RoundingMode.HALF_UP);
        LocalDateTime completedAt = status == AnalysisBatchStatus.PROCESSING
                ? null
                : aggregate.getLastCompletedAt();

        return new AnalysisBatchProgressResponse(
                aggregate.getBatchId(),
                aggregate.getBatchNo(),
                aggregate.getCourseId(),
                aggregate.getOriginalFilename(),
                status.name(),
                total,
                waiting,
                processing,
                retrying,
                success,
                failed,
                percentage,
                aggregate.getCreatedAt(),
                completedAt
        );
    }

    private static AnalysisBatchStatus resolveStatus(
            int total,
            int success,
            int failed) {
        if (success + failed < total) {
            return AnalysisBatchStatus.PROCESSING;
        }
        if (failed == 0) {
            return AnalysisBatchStatus.COMPLETED;
        }
        if (success == 0) {
            return AnalysisBatchStatus.FAILED;
        }
        return AnalysisBatchStatus.PARTIAL_FAILED;
    }

    private static int toInt(Long value) {
        return value == null ? 0 : Math.toIntExact(value);
    }
}

package com.courseinsight.server.service;

import com.baomidou.mybatisplus.core.metadata.IPage;
import com.baomidou.mybatisplus.extension.plugins.pagination.Page;
import com.courseinsight.server.common.PageResponse;
import com.courseinsight.server.dto.AnalysisBatchResultItemResponse;
import com.courseinsight.server.dto.AnalysisBatchResultPageQuery;
import com.courseinsight.server.dto.AnalysisBatchResultRow;
import com.courseinsight.server.entity.AnalysisBatch;
import com.courseinsight.server.entity.UserRole;
import com.courseinsight.server.exception.ResourceNotFoundException;
import com.courseinsight.server.mapper.AnalysisBatchMapper;
import com.courseinsight.server.mapper.AnalysisBatchResultMapper;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.csv.CSVFormat;
import org.apache.commons.csv.CSVPrinter;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class AnalysisBatchResultService {

    private static final int EXPORT_PAGE_SIZE = 100;
    private static final CSVFormat EXPORT_CSV_FORMAT = CSVFormat.DEFAULT.builder()
            .setHeader(
                    "任务ID",
                    "评论ID",
                    "评论内容",
                    "评分",
                    "任务状态",
                    "重试次数",
                    "语言",
                    "情感",
                    "置信度",
                    "风险等级",
                    "关键词",
                    "主题",
                    "教学建议",
                    "失败原因",
                    "完成时间"
            )
            .get();

    private final AnalysisBatchMapper batchMapper;
    private final AnalysisBatchResultMapper resultMapper;
    private final CourseManagementAccessService accessService;
    private final ObjectMapper objectMapper;

    public AnalysisBatchResultService(
            AnalysisBatchMapper batchMapper,
            AnalysisBatchResultMapper resultMapper,
            CourseManagementAccessService accessService,
            ObjectMapper objectMapper) {
        this.batchMapper = batchMapper;
        this.resultMapper = resultMapper;
        this.accessService = accessService;
        this.objectMapper = objectMapper;
    }

    @Transactional(readOnly = true)
    public PageResponse<AnalysisBatchResultItemResponse> page(
            Long batchId,
            Long currentUserId,
            UserRole currentRole,
            AnalysisBatchResultPageQuery query) {
        AnalysisBatch batch = requireBatch(batchId);
        accessService.assertCanManage(
                batch.getCourseId(),
                currentUserId,
                currentRole
        );

        IPage<AnalysisBatchResultRow> result = resultMapper.selectPageByBatchId(
                new Page<>(query.page(), query.size()),
                batchId
        );
        List<AnalysisBatchResultItemResponse> items = result.getRecords()
                .stream()
                .map(row -> AnalysisBatchResultItemResponse.from(row, objectMapper))
                .toList();

        return new PageResponse<>(
                result.getCurrent(),
                result.getSize(),
                result.getTotal(),
                result.getPages(),
                items
        );
    }

    @Transactional(readOnly = true)
    public String authorizeCsvExport(
            Long batchId,
            Long currentUserId,
            UserRole currentRole) {
        AnalysisBatch batch = requireBatch(batchId);
        accessService.assertCanManage(
                batch.getCourseId(),
                currentUserId,
                currentRole
        );
        return "analysis-batch-" + batch.getBatchNo() + ".csv";
    }

    public void writeCsv(Long batchId, OutputStream outputStream) throws IOException {
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(
                outputStream,
                StandardCharsets.UTF_8
        ));
        writer.write('\uFEFF');

        CSVPrinter printer = new CSVPrinter(writer, EXPORT_CSV_FORMAT);
        long pageNumber = 1;
        while (true) {
            IPage<AnalysisBatchResultRow> resultPage =
                    resultMapper.selectPageByBatchId(
                            new Page<>(pageNumber, EXPORT_PAGE_SIZE, false),
                            batchId
                    );
            List<AnalysisBatchResultRow> rows = resultPage.getRecords();
            if (rows.isEmpty()) {
                break;
            }

            for (AnalysisBatchResultRow row : rows) {
                printer.printRecord(
                        row.getTaskId(),
                        row.getCommentId(),
                        safeForSpreadsheet(row.getContent()),
                        row.getRating(),
                        row.getTaskStatus(),
                        row.getRetryCount(),
                        row.getLanguage(),
                        row.getSentiment(),
                        row.getConfidence(),
                        row.getRiskLevel(),
                        row.getKeywordsJson(),
                        row.getTopicsJson(),
                        row.getAdviceJson(),
                        safeForSpreadsheet(row.getFailureReason()),
                        formatDateTime(row.getTaskCompletedAt())
                );
            }
            printer.flush();

            if (rows.size() < EXPORT_PAGE_SIZE) {
                break;
            }
            pageNumber++;
        }
        printer.flush();
    }

    private String safeForSpreadsheet(String value) {
        if (value == null || value.isEmpty()) {
            return value;
        }
        char first = value.charAt(0);
        if (first == '=' || first == '+' || first == '-'
                || first == '@' || first == '\t' || first == '\r') {
            return "'" + value;
        }
        return value;
    }

    private String formatDateTime(LocalDateTime value) {
        return value == null ? "" : value.toString();
    }

    private AnalysisBatch requireBatch(Long batchId) {
        AnalysisBatch batch = batchMapper.selectById(batchId);
        if (batch == null) {
            throw new ResourceNotFoundException("批量分析任务不存在");
        }
        return batch;
    }
}

package com.courseinsight.server.controller;

import com.courseinsight.server.common.ApiResponse;
import com.courseinsight.server.common.PageResponse;
import com.courseinsight.server.dto.AnalysisBatchCreateResponse;
import com.courseinsight.server.dto.AnalysisBatchProgressResponse;
import com.courseinsight.server.dto.AnalysisBatchResultItemResponse;
import com.courseinsight.server.dto.AnalysisBatchResultPageQuery;
import com.courseinsight.server.dto.AnalysisBatchRetryResponse;
import com.courseinsight.server.security.CurrentUser;
import com.courseinsight.server.service.AnalysisBatchRecoveryService;
import com.courseinsight.server.service.AnalysisBatchResultService;
import com.courseinsight.server.service.AnalysisBatchService;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.validation.Valid;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.ModelAttribute;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestPart;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

import java.io.IOException;
import java.nio.charset.StandardCharsets;

@RestController
@RequestMapping("/api")
public class AnalysisBatchController {

    private final AnalysisBatchService batchService;
    private final AnalysisBatchResultService resultService;
    private final AnalysisBatchRecoveryService recoveryService;

    public AnalysisBatchController(
            AnalysisBatchService batchService,
            AnalysisBatchResultService resultService,
            AnalysisBatchRecoveryService recoveryService) {
        this.batchService = batchService;
        this.resultService = resultService;
        this.recoveryService = recoveryService;
    }

    @PostMapping(
            value = "/courses/{courseId}/analysis-batches",
            consumes = MediaType.MULTIPART_FORM_DATA_VALUE
    )
    @ResponseStatus(HttpStatus.CREATED)
    public ApiResponse<AnalysisBatchCreateResponse> upload(
            @PathVariable Long courseId,
            Authentication authentication,
            @RequestPart("file") MultipartFile file) {
        CurrentUser currentUser = CurrentUser.from(authentication);
        return ApiResponse.success(batchService.upload(
                courseId,
                currentUser.id(),
                currentUser.role(),
                file
        ));
    }

    @GetMapping("/analysis-batches/{batchId}")
    public ApiResponse<AnalysisBatchProgressResponse> getProgress(
            @PathVariable Long batchId,
            Authentication authentication) {
        CurrentUser currentUser = CurrentUser.from(authentication);
        return ApiResponse.success(batchService.getProgress(
                batchId,
                currentUser.id(),
                currentUser.role()
        ));
    }

    @GetMapping("/analysis-batches/{batchId}/results")
    public ApiResponse<PageResponse<AnalysisBatchResultItemResponse>> getResults(
            @PathVariable Long batchId,
            Authentication authentication,
            @Valid @ModelAttribute AnalysisBatchResultPageQuery query) {
        CurrentUser currentUser = CurrentUser.from(authentication);
        return ApiResponse.success(resultService.page(
                batchId,
                currentUser.id(),
                currentUser.role(),
                query
        ));
    }

    @GetMapping(
            value = "/analysis-batches/{batchId}/export",
            produces = "text/csv"
    )
    public void exportResults(
            @PathVariable Long batchId,
            Authentication authentication,
            HttpServletResponse response) throws IOException {
        CurrentUser currentUser = CurrentUser.from(authentication);
        String filename = resultService.authorizeCsvExport(
                batchId,
                currentUser.id(),
                currentUser.role()
        );

        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setContentType("text/csv");
        response.setHeader(
                HttpHeaders.CONTENT_DISPOSITION,
                ContentDisposition.attachment()
                        .filename(filename)
                        .build()
                        .toString()
        );
        resultService.writeCsv(batchId, response.getOutputStream());
    }

    @PostMapping("/analysis-batches/{batchId}/retry-failed")
    @ResponseStatus(HttpStatus.ACCEPTED)
    public ApiResponse<AnalysisBatchRetryResponse> retryFailed(
            @PathVariable Long batchId,
            Authentication authentication) {
        CurrentUser currentUser = CurrentUser.from(authentication);
        return ApiResponse.success(recoveryService.retryDeadLettered(
                batchId,
                currentUser.id(),
                currentUser.role()
        ));
    }
}

package com.courseinsight.server.service;

import com.courseinsight.server.cache.CourseAnalyticsCache;
import com.courseinsight.server.cache.CoursePopularityRankingCache;
import com.courseinsight.server.dto.AnalysisBatchCommentRow;
import com.courseinsight.server.dto.AnalysisBatchCreateResponse;
import com.courseinsight.server.entity.AnalysisBatch;
import com.courseinsight.server.entity.AnalysisOutboxEvent;
